{{st|Slow|{{ap|20 to 36}}%}}
|description2 = If ''Ice Shard'' hits an enemy, it will shatter, increasing its width and maximum range.
|cooldown     = {{ap|7 to 3}}
|cost         = {{ap|55 to 75}}
|cast time    = {{fd|0.25}}
|costtype     = Mana
|range        = {{dv|{{tip|cr|icononly = true}} {{tt|825|Standard range including area check after missile end}}|{{tt|950|Enhanced range from cast origin}}}}
|width        = {{dv|{{tip|er|icononly = true}} {{tt|150|Standard missile width}}|{{tt|180|Missile width after shattering}}}}
|speed        = {{tt|2200|Missile speed before and after shattering}}
|targeting    = Direction
